select * from (select order_id, status, cost from shipments)
pivot (sum(cost) for status in ('IN_TRANSIT', 'RETURNED', 'DELIVERED', 'LOST'))
order by order_id;

SELECT * FROM (SELECT status, method, amount FROM payments)
PIVOT (SUM(amount) FOR method IN ('promptpay', 'bank_transfer', 'card'))
ORDER BY status;

SELECT id, customer_id, COUNT(*) OVER (PARTITION BY customer_id) AS customer_id_count
FROM subscriptions
WHERE customer_id IS NOT NULL;

SELECT * FROM (SELECT page, event_type, duration_sec FROM web_events)
PIVOT (AVG(duration_sec) FOR event_type IN ('click', 'purchase', 'search', 'page_view'))
ORDER BY page;

SELECT * FROM (SELECT level, job_title, salary FROM employees)
PIVOT (MAX(salary) FOR job_title IN ('Intern', 'Designer', 'Director', 'Engineer'))
ORDER BY level;

SELECT * FROM (SELECT event_type, page, duration_sec FROM web_events)
PIVOT (MAX(duration_sec) FOR page IN ('/search', '/home', '/checkout'))
ORDER BY event_type;

SELECT * FROM (SELECT country, city, rating FROM suppliers)
PIVOT (SUM(rating) FOR city IN ('Singapore', 'Tokyo', 'Bangkok'))
ORDER BY country;

SELECT id, event_time
FROM web_events
WHERE event_time < '2023-06-18' AND duration_sec = 183;

select * from (select status, plan, monthly_fee from subscriptions)
pivot (avg(monthly_fee) for plan in ('standard', 'enterprise', 'premium', 'basic'))
order by status;

SELECT * FROM (SELECT city, region, sqft FROM stores WHERE LOWER(store_name) LIKE '%iam%')
PIVOT (MAX(sqft) FOR region IN ('West', 'North', 'East', 'South'))
ORDER BY city;

SELECT * FROM (SELECT category, brand, cost FROM products)
PIVOT (SUM(cost) FOR brand IN ('Acme', 'Umbrella', 'Initech'))
ORDER BY category;

SELECT o.id, o.discount
FROM orders o
WHERE EXISTS (SELECT 1 FROM shipments s WHERE s.order_id = o.id);

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (MAX(rating) FOR country IN ('SG', 'UK', 'TH'))
ORDER BY city;

SELECT * FROM (SELECT customer_id, status, monthly_fee FROM subscriptions)
PIVOT (AVG(monthly_fee) FOR status IN ('ACTIVE', 'CANCELLED', 'PAUSED'))
ORDER BY customer_id;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (SUM(rating) FOR country IN ('DE', 'US', 'UK', 'SG'))
ORDER BY city;

SELECT s.id, s.city, s.sqft
FROM stores s
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.store_id = s.id AND o.shipping_fee <= 30);
